// request
{ "jsonrpc": "2.0", "id": "req-a1", "method": "tools/list" }

// response, same id, copied exactly
{ "jsonrpc": "2.0", "id": "req-a1", "result": { "tools": [] } }

let nextId = 1;
const pending = new Map();

function sendRequest(method, params) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    transport.send({ jsonrpc: "2.0", id, method, params });
  });
}

// unsafe: id 5 chosen while a previous request with id 5 may still be pending
function badSend(method, params) {
  const id = Math.floor(Math.random() * 10); // small range, collisions likely
  transport.send({ jsonrpc: "2.0", id, method, params });
}

// three requests fired without waiting for each other
const [tools, resources, prompts] = await Promise.all([
  sendRequest("tools/list", {}),
  sendRequest("resources/list", {}),
  sendRequest("prompts/list", {})
]);

class RequestTracker {
  constructor() {
    this.nextId = 1;
    this.pending = new Map();
  }
  register(resolve, reject) {
    const id = this.nextId++;
    this.pending.set(id, { resolve, reject });
    return id;
  }
  resolveResponse(message) {
    const entry = this.pending.get(message.id);
    if (!entry) return false; // unknown id, safely ignored
    this.pending.delete(message.id);
    if ("result" in message) entry.resolve(message.result);
    else entry.reject(message.error);
    return true;
  }
}
